// ================================================================
// password.ts — 密码哈希/校验（scrypt + 盐）
// 零额外依赖，仅用 node:crypto
// 从应用侧 auth.ts 抽入，新应用无需自行实现密码工具
// ================================================================

import { scryptSync, randomBytes, timingSafeEqual } from 'node:crypto'
import type { PasswordService } from './types'

const KEY_LEN = 64

/** 密码哈希：scrypt + 16 字节随机盐，格式 `salt:hash` */
export function hashPassword(password: string): string {
  const salt = randomBytes(16).toString('hex')
  const hash = scryptSync(password, salt, KEY_LEN).toString('hex')
  return `${salt}:${hash}`
}

/** 密码校验：常量时间比较，防时序攻击 */
export function verifyPassword(password: string, stored: string): boolean {
  const [salt, hash] = stored.split(':')
  if (!salt || !hash) return false
  const hashBuf = Buffer.from(hash, 'hex')
  const testBuf = scryptSync(password, salt, KEY_LEN)
  if (hashBuf.length !== testBuf.length) return false
  return timingSafeEqual(hashBuf, testBuf)
}

/** 默认密码服务（scrypt 实现），应用不注入 passwordService 时使用 */
export const defaultPasswordService: PasswordService = {
  hash: hashPassword,
  verify: verifyPassword,
}
