// ================================================================
// token.ts — HMAC-SHA256 token 签发/验证（默认 TokenService 实现）
// 签名格式: base64url(payload).base64url(hmacSig)
// ================================================================

import { createHmac, timingSafeEqual } from 'node:crypto'
import type { TokenService } from './types'

export interface TokenServiceOptions {
  secret: string
  ttlMs?: number // 默认 7 天
}

export function createTokenService(opts: TokenServiceOptions): TokenService {
  const secret = opts.secret
  const ttlMs = opts.ttlMs ?? 7 * 24 * 60 * 60 * 1000

  return {
    sign(userId: string): string {
      const payload = { userId, iat: Date.now(), exp: Date.now() + ttlMs }
      const data = Buffer.from(JSON.stringify(payload)).toString('base64url')
      const sig = createHmac('sha256', secret).update(data).digest('base64url')
      return `${data}.${sig}`
    },

    verify(token: string): { userId: string } | null {
      const [data, sig] = token.split('.')
      if (!data || !sig) return null
      const expectedSig = createHmac('sha256', secret).update(data).digest('base64url')
      // 长度不等直接返回，避免 timingSafeEqual 抛异常
      if (sig.length !== expectedSig.length) return null
      if (!timingSafeEqual(Buffer.from(sig), Buffer.from(expectedSig))) return null
      try {
        const payload = JSON.parse(Buffer.from(data, 'base64url').toString())
        if (payload.exp && payload.exp < Date.now()) return null
        return { userId: payload.userId as string }
      } catch {
        return null
      }
    },
  }
}
