// ================================================================
// errors.ts — 统一错误响应（附录 B 矩阵）
// 所有认证/授权失败返回统一的 { error: string } 格式
// ================================================================

import type { Context } from 'hono'
import type { ContentfulStatusCode } from 'hono/utils/http-status'

type ErrorBody = { error: string }

function jsonError(c: Context, status: ContentfulStatusCode, message: string) {
  return c.json({ error: message } satisfies ErrorBody, status)
}

// --- 认证错误 (401) ---
export const ErrNotAuthenticated = (c: Context) => jsonError(c, 401, 'Not authenticated')
export const ErrAmbiguousCredentials = (c: Context) => jsonError(c, 401, 'Ambiguous credentials')
export const ErrInvalidLingeeCode = (c: Context) => jsonError(c, 401, 'Invalid lingee code')
export const ErrIdentityServiceUnavailable = (c: Context) => jsonError(c, 401, 'Identity service unavailable')
export const ErrTokenRevoked = (c: Context) => jsonError(c, 401, 'Token revoked or expired')
export const ErrTokenInvalid = (c: Context) => jsonError(c, 401, 'Token invalid')
export const ErrAccountDisabled = (c: Context) => jsonError(c, 401, 'Account disabled')
export const ErrSessionExpired = (c: Context) => jsonError(c, 401, 'Session expired, please log in again')

// --- 授权错误 (403) ---
export const ErrUserNotRegistered = (c: Context) => jsonError(c, 403, 'User not registered in this application')
export const ErrTenantNotAllowed = (c: Context) => jsonError(c, 403, 'Tenant not allowed')
export const ErrInvalidAppKey = (c: Context) => jsonError(c, 403, 'Invalid app key')
export const ErrInsufficientPermissions = (c: Context) => jsonError(c, 403, 'Insufficient permissions, admin role required')

// --- SSO 错误 (400) ---
export const ErrInvalidState = (c: Context) => jsonError(c, 400, 'Invalid state')
export const ErrStateExpired = (c: Context) => jsonError(c, 400, 'State expired')
export const ErrInvalidSsoTicket = (c: Context) => jsonError(c, 400, 'Invalid or expired SSO ticket')

// --- 失败原因分类（用于审计日志）---
export type FailReason =
  | 'auth_failed'
  | 'authz_failed'
  | 'business_error'
  | 'identity_service_error'

export function classifyFailReason(status: number): FailReason | undefined {
  if (status === 401) return 'auth_failed'
  if (status === 403) return 'authz_failed'
  if (status >= 500) return 'identity_service_error'
  if (status >= 400) return 'business_error'
  return undefined
}
