// ================================================================
// rate-limit.ts — 简单内存限流中间件
// 基于 IP + 路径的滑窗计数，适用于单实例部署
// 多实例需替换为 Redis 实现
// ================================================================

import type { MiddlewareHandler } from 'hono'
import type { ContentfulStatusCode } from 'hono/utils/http-status'

export interface RateLimitOptions {
  windowMs: number   // 时间窗口（毫秒）
  maxRequests: number // 窗口内最大请求数
  message?: string   // 超限时的错误消息
}

export function createRateLimit(opts: RateLimitOptions): MiddlewareHandler {
  const requests = new Map<string, { count: number; resetTime: number }>()
  const message = opts.message ?? 'Too many requests, please try again later'

  // 定期清理过期条目
  const timer = setInterval(() => {
    const now = Date.now()
    for (const [key, entry] of requests) {
      if (entry.resetTime <= now) requests.delete(key)
    }
  }, opts.windowMs)
  timer.unref?.()

  return async (c, next) => {
    const ip =
      c.req.header('x-forwarded-for')?.split(',')[0]?.trim() ??
      c.req.header('x-real-ip') ??
      'unknown'
    const key = `${ip}:${c.req.path}`
    const now = Date.now()

    const entry = requests.get(key)
    if (!entry || entry.resetTime <= now) {
      requests.set(key, { count: 1, resetTime: now + opts.windowMs })
    } else {
      entry.count++
      if (entry.count > opts.maxRequests) {
        return c.json({ error: message }, 429 as ContentfulStatusCode)
      }
    }

    await next()
  }
}
