// ================================================================
// lingee-auth.ts — 灵基 Console Token 验证
// 流程: x-lingee-code → exchange → userinfo → 本地用户映射 → 缓存
// code 一次性，exchange 后缓存 accessToken，后续请求命中缓存 + 按需 verify
// ================================================================

import { createHash } from 'node:crypto'
import type {
  AppUser, Cache, CachedLingeeIdentity, LingeeTokenExchange,
  LingeeTokenVerify, LingeeUserInfo, UserResolver,
} from './types'
import type { AuthKitConfig } from './config'
import { dbg, maskHash, maskToken } from './debug'

// --- Console 接口路径 ---
const EXCHANGE_PATH = '/console/api/open/auth/token/exchange'
const VERIFY_PATH = '/console/api/open/auth/token/verify'
const USERINFO_PATH = '/console/api/open/auth/token/userinfo'
const REFRESH_PATH = '/console/api/open/auth/token/refresh'

export interface LingeeAuthOptions<U extends AppUser> {
  consoleUrl: string
  cache: Cache
  config: AuthKitConfig
  userResolver: UserResolver<U>
  verifyCacheTtlMs?: number // 默认 30s
}

export type LingeeAuthResult<U extends AppUser> =
  | { ok: true; user: U; identity: LingeeUserInfo }
  | { ok: false; error: string; statusCode: number }

// ================================================================
// Console API 调用（fail-closed：网络错误一律返回 null）
// ================================================================

async function callExchange(
  consoleUrl: string,
  code: string,
): Promise<LingeeTokenExchange | null> {
  const codeHash = createHash('sha256').update(code).digest('hex').slice(0, 8)
  dbg('exchange', `POST ${consoleUrl}${EXCHANGE_PATH} code=${codeHash}…`)
  try {
    const res = await fetch(`${consoleUrl}${EXCHANGE_PATH}`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ code }),
    })
    if (!res.ok) {
      dbg('exchange', `FAIL HTTP ${res.status} — code 无效或过期`)
      return null // 400 = code 无效/过期
    }
    const json = (await res.json()) as { code: number; data?: LingeeTokenExchange }
    if (json.code !== 0 || !json.data) {
      dbg('exchange', `FAIL biz code=${json.code} — Console 业务层拒绝`)
      return null
    }
    dbg('exchange', `OK sysUserId=${json.data.sysUserId} tenantId=${json.data.tenantId} token=${maskToken(json.data.accessToken)}`)
    return json.data
  } catch (err) {
    dbg('exchange', `NETWORK ERROR — ${err instanceof Error ? err.message : String(err)}`)
    return null // 网络超时/不可达 → fail-closed
  }
}

async function callVerify(
  consoleUrl: string,
  accessToken: string,
): Promise<LingeeTokenVerify | null> {
  dbg('verify', `POST ${consoleUrl}${VERIFY_PATH} token=${maskToken(accessToken)}`)
  try {
    const res = await fetch(`${consoleUrl}${VERIFY_PATH}`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ token: accessToken }),
    })
    if (!res.ok) {
      dbg('verify', `FAIL HTTP ${res.status}`)
      return null
    }
    const json = (await res.json()) as { code: number; data?: LingeeTokenVerify }
    if (json.code !== 0 || !json.data) {
      dbg('verify', `FAIL biz code=${json.code}`)
      return null
    }
    dbg('verify', `OK valid=${json.data.valid}`)
    return json.data
  } catch (err) {
    dbg('verify', `NETWORK ERROR — ${err instanceof Error ? err.message : String(err)}`)
    return null // 网络超时/不可达 → fail-closed
  }
}

async function callUserinfo(
  consoleUrl: string,
  accessToken: string,
): Promise<LingeeUserInfo | null> {
  dbg('userinfo', `GET ${consoleUrl}${USERINFO_PATH} token=${maskToken(accessToken)}`)
  try {
    const res = await fetch(`${consoleUrl}${USERINFO_PATH}`, {
      method: 'GET',
      headers: { Authorization: `Bearer ${accessToken}` },
    })
    if (!res.ok) {
      dbg('userinfo', `FAIL HTTP ${res.status} — token 无效`)
      return null // 401 = token 无效
    }
    const json = (await res.json()) as { code: number; data?: LingeeUserInfo }
    if (json.code !== 0 || !json.data) {
      dbg('userinfo', `FAIL biz code=${json.code}`)
      return null
    }
    dbg('userinfo', `OK tenantCode=${json.data.tenantCode} username=${json.data.username} truename=${json.data.truename} phone=${json.data.phone ?? 'null'}`)
    return json.data
  } catch (err) {
    dbg('userinfo', `NETWORK ERROR — ${err instanceof Error ? err.message : String(err)}`)
    return null // 网络超时/不可达 → fail-closed
  }
}

async function callRefresh(
  consoleUrl: string,
  refreshToken: string,
): Promise<{ accessToken: string; refreshToken: string; expiresAt: number } | null> {
  dbg('refresh', `POST ${consoleUrl}${REFRESH_PATH} token=${maskToken(refreshToken)}`)
  try {
    const res = await fetch(`${consoleUrl}${REFRESH_PATH}`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ refreshToken }),
    })
    if (!res.ok) {
      dbg('refresh', `FAIL HTTP ${res.status}`)
      return null
    }
    const json = (await res.json()) as {
      code: number
      data?: { accessToken: string; refreshToken: string; expiresAt: number }
    }
    if (json.code !== 0 || !json.data) {
      dbg('refresh', `FAIL biz code=${json.code}`)
      return null
    }
    dbg('refresh', `OK newToken=${maskToken(json.data.accessToken)} expiresAt=${json.data.expiresAt}`)
    return json.data
  } catch (err) {
    dbg('refresh', `NETWORK ERROR — ${err instanceof Error ? err.message : String(err)}`)
    return null
  }
}

// ================================================================
// 核心验证函数
// ================================================================

export async function verifyLingeeCode<U extends AppUser>(
  code: string,
  opts: LingeeAuthOptions<U>,
): Promise<LingeeAuthResult<U>> {
  // 1. code hash 作为缓存 key（不存原始 code）
  const codeHash = createHash('sha256').update(code).digest('hex')
  const cacheKey = `lingee:${codeHash}`
  const verifyTtl = opts.verifyCacheTtlMs ?? 30_000
  dbg('verify', `── verifyLingeeCode 开始 code=${maskHash(codeHash)} consoleUrl=${opts.consoleUrl}`)

  // 2. 查缓存
  const cached = await opts.cache.get<CachedLingeeIdentity>(cacheKey)

  if (cached) {
    dbg('verify', `缓存命中 localUserId=${cached.localUserId} token=${maskToken(cached.accessToken)}`)
    // 3. accessToken 是否已过期
    if (cached.expiresAt * 1000 < Date.now()) {
      dbg('verify', `accessToken 已过期 → 尝试 refresh`)
      // 尝试用 refreshToken 续期
      const refreshResult = await callRefresh(opts.consoleUrl, cached.refreshToken)
      if (refreshResult) {
        cached.accessToken = refreshResult.accessToken
        cached.refreshToken = refreshResult.refreshToken
        cached.expiresAt = refreshResult.expiresAt
        cached.lastVerifiedAt = Date.now()
        const remainingMs = Math.max(0, refreshResult.expiresAt * 1000 - Date.now())
        await opts.cache.set(cacheKey, cached, remainingMs)
        dbg('verify', `refresh 成功 → 缓存已更新`)
      } else {
        await opts.cache.delete(cacheKey)
        dbg('verify', `refresh 失败 → 缓存删除 → 返回 401 Token revoked`)
        return { ok: false, error: 'Token revoked or expired', statusCode: 401 }
      }
    }

    // 4. 按需 verify（距上次 verify 超过 verifyTtl 才调 Console）
    if (Date.now() - cached.lastVerifiedAt > verifyTtl) {
      dbg('verify', `距上次 verify 超过 ${verifyTtl}ms → 按需 verify`)
      const verifyResult = await callVerify(opts.consoleUrl, cached.accessToken)
      if (!verifyResult || !verifyResult.valid) {
        await opts.cache.delete(cacheKey)
        dbg('verify', `verify 失败 → 缓存删除 → 返回 401 Token revoked`)
        return { ok: false, error: 'Token revoked or expired', statusCode: 401 }
      }
      // 更新 lastVerifiedAt，刷新缓存 TTL
      cached.lastVerifiedAt = Date.now()
      const remainingMs = Math.max(0, cached.expiresAt * 1000 - Date.now())
      await opts.cache.set(cacheKey, cached, remainingMs)
      dbg('verify', `verify 成功 → lastVerifiedAt 已更新`)
    }

    // 5. 从缓存取本地用户（可能已被禁用）
    const user = await opts.userResolver.findById(cached.localUserId)
    if (!user || user.status !== (opts.config.activeStatus ?? 'active')) {
      dbg('verify', `本地用户 ${cached.localUserId} 不存在或 disabled → 返回 401`)
      return { ok: false, error: 'Account disabled', statusCode: 401 }
    }
    dbg('verify', `── 缓存路径完成 → 认证成功 user=${user.id}(${user.role})`)
    return { ok: true, user, identity: cached.identity }
  }

  // 6. 缓存未命中 → exchange
  dbg('verify', `缓存未命中 → 首次认证流程`)
  const exchangeResult = await callExchange(opts.consoleUrl, code)
  if (!exchangeResult) {
    dbg('verify', `exchange 失败 → 返回 401 Invalid lingee code`)
    return { ok: false, error: 'Invalid lingee code', statusCode: 401 }
  }

  // 7. userinfo
  const userInfo = await callUserinfo(opts.consoleUrl, exchangeResult.accessToken)
  if (!userInfo) {
    dbg('verify', `userinfo 失败 → 返回 401 Token invalid`)
    return { ok: false, error: 'Token invalid', statusCode: 401 }
  }

  // 8. 租户白名单校验
  if (
    opts.config.lingeeTenantCodeWhitelist &&
    opts.config.lingeeTenantCodeWhitelist.length > 0 &&
    !opts.config.lingeeTenantCodeWhitelist.includes(userInfo.tenantCode)
  ) {
    dbg('verify', `租户 ${userInfo.tenantCode} 不在白名单 [${opts.config.lingeeTenantCodeWhitelist.join(',')}] → 返回 403`)
    return { ok: false, error: 'Tenant not allowed', statusCode: 403 }
  }
  dbg('verify', `租户校验通过 tenantCode=${userInfo.tenantCode}`)

  // 9. 本地用户映射（多字段遍历，第一个匹配成功的即返回）
  const matchFields = opts.config.matchFields
    ?? [{ externalField: 'phone', localField: 'phone' }]
  let user: U | null = null
  for (const { externalField, localField } of matchFields) {
    const fieldValue = (userInfo as unknown as Record<string, unknown>)[externalField] as string | null
    if (!fieldValue) {
      dbg('verify', `跳过 ${externalField}→${localField}：userinfo 中为 null`)
      continue
    }
    const found = await opts.userResolver.findByField(localField, fieldValue)
    if (found) {
      user = found
      dbg('verify', `本地用户映射成功 ${externalField}→${localField}=${fieldValue} → user=${found.id}(${found.role})`)
      break
    }
    dbg('verify', `${externalField}→${localField}=${fieldValue} 本地无匹配用户`)
  }
  if (!user) {
    dbg('verify', `所有字段映射均未匹配 → 返回 403 User not registered`)
    return { ok: false, error: 'User not registered in this application', statusCode: 403 }
  }
  if (user.status !== (opts.config.activeStatus ?? 'active')) {
    dbg('verify', `本地用户 ${user.id} status=${user.status} → 返回 401 Account disabled`)
    return { ok: false, error: 'Account disabled', statusCode: 401 }
  }

  // 10. 写缓存（TTL = accessToken 剩余有效期）
  const cacheEntry: CachedLingeeIdentity = {
    accessToken: exchangeResult.accessToken,
    refreshToken: exchangeResult.refreshToken,
    expiresAt: exchangeResult.expiresAt,
    identity: userInfo,
    localUserId: user.id,
    lastVerifiedAt: Date.now(),
  }
  const cacheTtl = Math.max(0, exchangeResult.expiresAt * 1000 - Date.now())
  await opts.cache.set(cacheKey, cacheEntry, cacheTtl)
  dbg('verify', `缓存已写入 TTL=${cacheTtl}ms token=${maskToken(exchangeResult.accessToken)}`)
  dbg('verify', `── 首次认证流程完成 → 认证成功 user=${user.id}(${user.role})`)

  return { ok: true, user, identity: userInfo }
}
