// ================================================================
// oauth-sso.ts — OAuth2 SSO 路由工厂
// 流程: 灵基菜单 URL(authorize) → Kwork 302 回调 callback
//       → code 换 token → userinfo → 映射本地用户 → 签发 HMAC token → 302 到前端
// ================================================================

import { randomBytes } from 'node:crypto'
import type { Context } from 'hono'
import type {
  AppUser, AuditLogger, Cache, OAuthIdentity,
  OAuthTokenResponse, TokenService, UserResolver,
} from './types'
import type { AuthKitConfig } from './config'
import { ErrInvalidSsoTicket } from './errors'

export interface SsoRouteOptions<U extends AppUser> {
  userResolver: UserResolver<U>
  tokenService: TokenService
  cache: Cache
  config: AuthKitConfig
  auditLogger?: AuditLogger
}

export interface SsoRoutes {
  start: (c: Context) => Promise<Response>
  callback: (c: Context) => Promise<Response>
  exchange: (c: Context) => Promise<Response>
}

export function createSsoRoutes<U extends AppUser>(opts: SsoRouteOptions<U>): SsoRoutes {
  const { userResolver, tokenService, cache, config, auditLogger } = opts

  async function audit(method: string, route: string, statusCode: number, failReason?: string) {
    if (!auditLogger) return
    await auditLogger.log({
      ts: new Date().toISOString(),
      requestId: '-',
      channel: 'web',
      method,
      route,
      statusCode,
      failReason,
    })
  }

  // --- 从请求推导正确的 origin（考虑反向代理）---
  // nginx proxy_set_header X-Forwarded-Proto $scheme 后，
  // 后端 c.req.url 是 http，但 X-Forwarded-Proto: https
  function resolveOrigin(c: Context): string {
    const url = new URL(c.req.url)
    const forwardedProto = c.req.header('X-Forwarded-Proto')
    if (forwardedProto === 'https') {
      return `https://${url.host}`
    }
    return url.origin
  }

  // --- 推导 SSO 前端跳转地址 ---
  // 优先级：config.frontendUrl（FRONTEND_URL > CORS_ORIGIN）→ 请求推导
  // 如果已配置但是 http 且请求经过 HTTPS 代理，强制升级为 https
  function resolveFrontendUrl(c: Context): string {
    if (config.frontendUrl) {
      const forwardedProto = c.req.header('X-Forwarded-Proto')
      if (forwardedProto === 'https' && config.frontendUrl.startsWith('http://')) {
        return config.frontendUrl.replace(/^http:\/\//, 'https://')
      }
      return config.frontendUrl
    }
    return resolveOrigin(c)
  }

  // --- redirect_uri 自动推导 ---
  function resolveRedirectUri(c: Context): string {
    if (config.oauthRedirectUri) return config.oauthRedirectUri
    return `${resolveOrigin(c)}${config.ssoCallbackPath ?? '/api/auth/sso/callback'}`
  }

  // --- OAuth2 API 调用 ---
  async function exchangeCodeForToken(code: string, redirectUri: string): Promise<OAuthTokenResponse | null> {
    const tokenUrl = config.oauthTokenUrl
    console.log('[sso] Step 1: Exchanging code for token →', tokenUrl)
    console.log('[sso]   client_id:', config.oauthClientId)
    console.log('[sso]   redirect_uri:', redirectUri)
    try {
      const body = new URLSearchParams({
        grant_type: 'authorization_code',
        code,
        redirect_uri: redirectUri,
        client_id: config.oauthClientId ?? '',
        client_secret: config.oauthClientSecret ?? '',
      })
      const res = await fetch(tokenUrl!, {
        method: 'POST',
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
        body: body.toString(),
      })
      console.log('[sso]   Token endpoint response status:', res.status)
      if (!res.ok) {
        const text = await res.text().catch(() => '')
        console.error('[sso]   ✗ Token exchange failed:', res.status, text)
        return null
      }
      const data = (await res.json()) as OAuthTokenResponse
      console.log('[sso]   ✓ Token exchange success, access_token:', data.access_token?.slice(0, 20) + '...')
      return data
    } catch (err) {
      console.error('[sso]   ✗ Token exchange error:', err instanceof Error ? err.message : String(err))
      return null
    }
  }

  async function getUserinfo(accessToken: string): Promise<OAuthIdentity | null> {
    const userinfoUrl = config.oauthUserinfoUrl
    console.log('[sso] Step 2: Fetching userinfo →', userinfoUrl)
    try {
      const res = await fetch(userinfoUrl!, {
        method: 'GET',
        headers: { Authorization: `Bearer ${accessToken}` },
      })
      console.log('[sso]   Userinfo endpoint response status:', res.status)
      if (!res.ok) {
        const text = await res.text().catch(() => '')
        console.error('[sso]   ✗ Userinfo failed:', res.status, text)
        return null
      }
      const data = (await res.json()) as OAuthIdentity
      console.log('[sso]   ✓ Userinfo success:', { sub: data.sub, phone: data.phone, username: data.username, role: data.role })
      return data
    } catch (err) {
      console.error('[sso]   ✗ Userinfo error:', err instanceof Error ? err.message : String(err))
      return null
    }
  }

  // --- start: 生成 state，302 到 Kwork authorize ---
  async function start(c: Context): Promise<Response> {
    console.log('[sso] Start: generating state and redirecting to authorize')
    if (!config.oauthAuthorizeUrl || !config.oauthClientId) {
      console.error('[sso]   ✗ SSO not configured (missing authorize_url or client_id)')
      await audit('GET', config.ssoStartPath ?? '/api/auth/sso/start', 500, 'config_missing')
      return c.json({ error: 'SSO not configured' }, 500)
    }

    const state = randomBytes(32).toString('hex')
    const stateTtl = config.oauthStateTtlMs ?? 300_000
    await cache.set(`sso:state:${state}`, { created: Date.now() }, stateTtl)

    const url = new URL(config.oauthAuthorizeUrl)
    url.searchParams.set('response_type', 'code')
    url.searchParams.set('client_id', config.oauthClientId)
    url.searchParams.set('redirect_uri', resolveRedirectUri(c))
    url.searchParams.set('state', state)

    console.log('[sso]   → Redirecting to:', url.toString())
    return c.redirect(url.toString(), 302)
  }

  // --- callback: code → token → userinfo → 映射 → 签发 token → 302 前端 ---
  async function callback(c: Context): Promise<Response> {
    const code = c.req.query('code')
    const state = c.req.query('state')
    const frontendUrl = resolveFrontendUrl(c)

    const ssoCallbackPath = config.ssoCallbackPath ?? '/api/auth/sso/callback'
    const loginPath = config.loginPath ?? '/login'
    const tokenRedirect = config.tokenRedirectPath ?? '/?token={token}'
    const activeStatus = config.activeStatus ?? 'active'

    console.log('[sso] Callback received:', {
      code: code ? code.slice(0, 10) + '...' : 'null',
      state: state ?? 'null',
    })

    // state 校验（可选：灵基菜单 URL 中 state 是静态的，不在后端缓存中）
    if (state) {
      const stateKey = `sso:state:${state}`
      const stateEntry = await cache.get<{ created: number }>(stateKey)
      if (stateEntry) {
        console.log('[sso]   State found in cache, consuming')
        await cache.delete(stateKey)
      } else {
        console.log('[sso]   State not in cache (static state from menu URL, skipping validation)')
      }
    }

    if (!code) {
      console.error('[sso]   ✗ No code in callback')
      await audit('GET', ssoCallbackPath, 400, 'auth_failed')
      return c.redirect(`${frontendUrl}${loginPath}?sso_error=no_code`, 302)
    }

    // Step 1: code 换 token
    const tokenResp = await exchangeCodeForToken(code, resolveRedirectUri(c))
    if (!tokenResp) {
      await audit('GET', ssoCallbackPath, 401, 'auth_failed')
      return c.redirect(`${frontendUrl}${loginPath}?sso_error=token_failed`, 302)
    }

    // Step 2: 获取用户信息
    const oauthUser = await getUserinfo(tokenResp.access_token)
    if (!oauthUser) {
      await audit('GET', ssoCallbackPath, 401, 'auth_failed')
      return c.redirect(`${frontendUrl}${loginPath}?sso_error=userinfo_failed`, 302)
    }

    // Step 3: 本地用户映射（多字段遍历，第一个匹配成功的即返回）
    const matchFields = config.matchFields
      ?? [{ externalField: 'phone', localField: 'phone' }]
    let user: U | null = null
    for (const { externalField, localField } of matchFields) {
      const fieldValue = (oauthUser as unknown as Record<string, unknown>)[externalField] as string | null
      if (!fieldValue) {
        console.log(`[sso]   - 跳过 ${externalField}→${localField}：userinfo 中为 null`)
        continue
      }
      console.log('[sso] Step 3: User mapping:', { externalField, localField, fieldValue })
      const found = await userResolver.findByField(localField, fieldValue)
      if (found) {
        user = found
        console.log('[sso]   User matched:', { id: found.id, role: found.role, status: found.status })
        break
      }
      console.log(`[sso]   - ${externalField}→${localField}=${fieldValue} 本地无匹配用户`)
    }

    if (!user) {
      console.error('[sso]   ✗ All match fields exhausted, no local user found')
      await audit('GET', ssoCallbackPath, 403, 'authz_failed')
      return c.redirect(`${frontendUrl}${loginPath}?sso_error=unbound`, 302)
    }
    if (user.status !== activeStatus) {
      console.error('[sso]   ✗ User disabled:', user.id, 'status:', user.status)
      await audit('GET', ssoCallbackPath, 401, 'auth_failed')
      return c.redirect(`${frontendUrl}${loginPath}?sso_error=disabled`, 302)
    }

    // Step 4: 签发 HMAC token，302 到前端
    const token = tokenService.sign(user.id)
    console.log('[sso] Step 4: Token signed for user:', user.id, '→ redirect to:', `${frontendUrl}${tokenRedirect.replace('{token}', '...')}`)
    await audit('GET', ssoCallbackPath, 302)
    return c.redirect(`${frontendUrl}${tokenRedirect.replace('{token}', token)}`, 302)
  }

  // --- exchange: sso_ticket → HMAC token（保留，当前流程不使用）---
  async function exchange(c: Context): Promise<Response> {
    const body = await c.req.json().catch(() => ({}))
    const ticket = body.ticket as string | undefined

    if (!ticket) {
      await audit('POST', config.ssoExchangePath ?? '/api/auth/sso/exchange', 400, 'auth_failed')
      return ErrInvalidSsoTicket(c)
    }

    const ticketKey = `sso:ticket:${ticket}`
    const ticketEntry = await cache.get<{ userId: string }>(ticketKey)
    if (!ticketEntry) {
      await audit('POST', config.ssoExchangePath ?? '/api/auth/sso/exchange', 400, 'auth_failed')
      return ErrInvalidSsoTicket(c)
    }
    await cache.delete(ticketKey)

    const token = tokenService.sign(ticketEntry.userId)
    await audit('POST', config.ssoExchangePath ?? '/api/auth/sso/exchange', 200)
    return c.json({ token })
  }

  return { start, callback, exchange }
}
