// ================================================================
// setup.ts — createAuth() 一站式认证工厂
// 新应用只需传入 UserResolver，即可获得全部认证能力：
//   - requireAnyAuth（MCP + Web 统一认证中间件）
//   - requireAdmin（管理员校验）
//   - sso（SSO 路由：start / callback / exchange）
//   - signToken（HMAC token 签发）
//   - loginRateLimit（登录限流）
//   - hashPassword / verifyPassword（密码工具）
//   - createLoginRoute（密码登录路由工厂）
// 其余依赖（config / tokenService / cache / auditLogger）自动创建
// ================================================================

import type { MiddlewareHandler } from 'hono'
import type {
  AppUser, AuthEnv, AuditLogger, CredentialUser,
  LoginRouteOptions, PasswordService, UserResolver,
} from './types'
import type { AuthKitConfig } from './config'
import { loadConfigFromEnv, assertConfig } from './config'
import { createTokenService } from './token'
import { createMemoryCache } from './cache'
import { createConsoleAuditLogger } from './audit'
import { createAuthMiddleware } from './middleware'
import { createSsoRoutes } from './oauth-sso'
import { createRateLimit } from './rate-limit'
import { hashPassword, verifyPassword } from './password'
import type { SsoRoutes } from './oauth-sso'

export interface AuthSetupOptions<U extends AppUser> {
  /** 应用实现的 UserResolver（查本地 users 表） */
  userResolver: UserResolver<U>
  /** 可选配置，不传则从环境变量自动读取 */
  config?: AuthKitConfig
  /** 可选审计日志器，不传用默认 console 输出 */
  auditLogger?: AuditLogger
  /** 可选密码服务，不传用默认 scrypt 实现（已有存量库用 bcrypt/argon2 等时注入） */
  passwordService?: PasswordService
  /** 限流配置，默认 60s 内最多 10 次 */
  rateLimit?: {
    windowMs?: number
    maxRequests?: number
    message?: string
  }
}

export interface AuthSetup<U extends AppUser> {
  /** 统一认证中间件（MCP x-lingee-code + Web Bearer token，互斥分流） */
  requireAnyAuth: MiddlewareHandler<AuthEnv<U>>
  /** 管理员校验（串联在 requireAnyAuth 之后） */
  requireAdmin: MiddlewareHandler<AuthEnv<U>>
  /** SSO 路由（start / callback / exchange） */
  sso: SsoRoutes
  /** HMAC token 签发（登录成功后调用） */
  signToken: (userId: string) => string
  /** 登录限流中间件 */
  loginRateLimit: MiddlewareHandler
  /** 密码哈希（scrypt + 盐） */
  hashPassword: (password: string) => string
  /** 密码校验（常量时间比较） */
  verifyPassword: (password: string, stored: string) => boolean
  /** 密码登录路由工厂（传入 findByCredential 即可生成登录路由） */
  createLoginRoute: <L extends CredentialUser>(opts: LoginRouteOptions<L>) => MiddlewareHandler
  /** 已加载的配置（供应用读取 adminRole / activeStatus 等） */
  config: AuthKitConfig
}

export function createAuth<U extends AppUser>(opts: AuthSetupOptions<U>): AuthSetup<U> {
  // 1. 配置：优先用传入的，否则从 env 读取
  const config = opts.config ?? loadConfigFromEnv()
  assertConfig(config)

  // 启动时输出各通道状态，便于排查 env 缺失问题
  const mcpOn = !!config.lingeeConsoleUrl
  const ssoOn = !!(config.oauthClientId && config.oauthClientSecret)
  console.log(
    `[authkit] channels: web=on | mcp=${mcpOn ? 'on' : 'off (LINGEE_CONSOLE_URL not set)'} | sso=${ssoOn ? 'on' : 'off (OAUTH_CLIENT_* not set)'}`,
  )

  // 2. 组装依赖
  const tokenService = createTokenService({
    secret: config.jwtSecret,
    ttlMs: config.tokenTtlMs,
  })
  const cache = createMemoryCache()
  const auditLogger = opts.auditLogger ?? createConsoleAuditLogger()

  // 3. 创建中间件 + SSO 路由
  const mw = createAuthMiddleware<U>({
    userResolver: opts.userResolver,
    tokenService,
    cache,
    config,
    auditLogger,
    passwordService: opts.passwordService,
  })
  const sso = createSsoRoutes({
    userResolver: opts.userResolver,
    tokenService,
    cache,
    config,
    auditLogger,
  })

  // 4. 限流
  const rl = opts.rateLimit ?? {}
  const loginRateLimit = createRateLimit({
    windowMs: rl.windowMs ?? 60_000,
    maxRequests: rl.maxRequests ?? 10,
    message: rl.message ?? 'Too many login attempts, please try again later',
  })

  return {
    requireAnyAuth: mw.requireAnyAuth,
    requireAdmin: mw.requireAdmin,
    sso,
    signToken: (userId: string) => tokenService.sign(userId),
    loginRateLimit,
    hashPassword: mw.hashPassword,
    verifyPassword: mw.verifyPassword,
    createLoginRoute: mw.createLoginRoute,
    config,
  }
}
