// ================================================================
// config.ts — 模块配置 + 环境变量读取 + 启动校验
// ================================================================

const DEFAULT_JWT_SECRET = 'authkit-dev-secret-change-in-prod'
const DEFAULT_TOKEN_TTL = 7 * 24 * 60 * 60 * 1000 // 7 天
const DEFAULT_VERIFY_CACHE_TTL = 30_000 // 30 秒
const DEFAULT_STATE_TTL = 300_000 // 5 分钟
const DEFAULT_SSO_TICKET_TTL = 30_000 // 30 秒

/**
 * 字段映射对：灵基/OAuth userinfo 中的字段 → 本地 users 表字段
 * 因为外部返回的字段名可能与本地表字段名不同
 * 例如：灵基 username → 本地 user_code
 */
export interface MatchFieldMapping {
  /** 外部 userinfo 中的字段名（如 phone / username） */
  externalField: string
  /** 本地 users 表的字段名（如 phone / user_code） */
  localField: string
}

export interface AuthKitConfig {
  // --- 认证 ---
  jwtSecret: string
  tokenTtlMs?: number

  // --- 角色与状态（可配置，默认 'admin' / 'active'）---
  /** 管理员角色标识，默认 'admin' */
  adminRole?: string
  /** 活跃用户状态标识，默认 'active' */
  activeStatus?: string

  // --- 用户匹配字段（MCP 和 SSO 共享）---
  /** 多字段映射，按顺序匹配，第一个匹配成功的用户即返回 */
  matchFields?: MatchFieldMapping[]

  // --- 灵基 MCP ---
  lingeeConsoleUrl?: string
  lingeeTenantCodeWhitelist?: string[]
  lingeeVerifyCacheTtlMs?: number

  // --- SSO (OAuth2) ---
  oauthClientId?: string
  oauthClientSecret?: string
  oauthAuthorizeUrl?: string
  oauthTokenUrl?: string
  oauthUserinfoUrl?: string
  oauthRedirectUri?: string
  oauthStateTtlMs?: number
  ssoTicketTtlMs?: number

  // --- 应用级凭证 ---
  appKey?: string

  // --- SSO 前端地址（SSO callback 成功后 302 跳转的目标）---
  frontendUrl?: string

  // --- 路由路径（可配置，新应用可覆盖默认值）---
  /** SSO callback 路径，默认 '/api/auth/sso/callback' */
  ssoCallbackPath?: string
  /** SSO start 路径，默认 '/api/auth/sso/start' */
  ssoStartPath?: string
  /** SSO exchange 路径，默认 '/api/auth/sso/exchange' */
  ssoExchangePath?: string
  /** 密码登录路由路径，默认 '/api/auth/login' */
  loginRoutePath?: string
  /** SSO 失败后跳转的前端路径，默认 '/login' */
  loginPath?: string
  /** SSO 成功后跳转的前端路径模板，默认 '/?token={token}' */
  tokenRedirectPath?: string
}

/**
 * 解析多字段映射配置字符串
 * 格式："externalField:localField,externalField:localField"
 * 例如："phone:phone,username:user_code"
 * - 先匹配 phone:phone（外部 phone → 本地 phone）
 * - 再匹配 username:user_code（外部 username → 本地 user_code）
 *
 * 向后兼容：如果值不含冒号，视为外部字段名 = 本地字段名
 * 例如："phone" 等价于 "phone:phone"
 */
export function parseMatchFields(raw: string): MatchFieldMapping[] {
  return raw
    .split(',')
    .map((s) => s.trim())
    .filter(Boolean)
    .map((pair) => {
      const [externalField, localField] = pair.split(':').map((s) => s.trim())
      return {
        externalField: externalField ?? pair,
        localField: localField ?? externalField ?? pair,
      }
    })
}

/**
 * 从 MATCH_FIELDS 环境变量推导映射数组
 * 未设置时回退到默认 phone:phone
 */
function resolveMatchFields(
  env: string | undefined,
  defaultField = 'phone',
): MatchFieldMapping[] {
  if (env) return parseMatchFields(env)
  return [{ externalField: defaultField, localField: defaultField }]
}

/** 从环境变量构建配置 */
export function loadConfigFromEnv(): AuthKitConfig {
  const jwtSecret = process.env.JWT_SECRET ?? DEFAULT_JWT_SECRET
  const lingeeTenantCode = process.env.LINGEE_TENANT_CODE
  const kworkBaseUrl = process.env.KWORK_BASE_URL
  return {
    jwtSecret,
    tokenTtlMs: DEFAULT_TOKEN_TTL,
    adminRole: process.env.ADMIN_ROLE ?? 'admin',
    activeStatus: process.env.ACTIVE_STATUS ?? 'active',
    lingeeConsoleUrl: process.env.LINGEE_CONSOLE_URL,
    matchFields: resolveMatchFields(process.env.MATCH_FIELDS),
    lingeeTenantCodeWhitelist: lingeeTenantCode
      ? lingeeTenantCode.split(',').map((s: string) => s.trim())
      : undefined,
    lingeeVerifyCacheTtlMs: DEFAULT_VERIFY_CACHE_TTL,
    oauthClientId: process.env.OAUTH_CLIENT_ID,
    oauthClientSecret: process.env.OAUTH_CLIENT_SECRET,
    // 3 个 URL 优先用单独配置，未配则从 KWORK_BASE_URL 自动推导
    oauthAuthorizeUrl: process.env.OAUTH_AUTHORIZE_URL ?? (kworkBaseUrl ? `${kworkBaseUrl}/oauth2/authorize` : undefined),
    oauthTokenUrl: process.env.OAUTH_TOKEN_URL ?? (kworkBaseUrl ? `${kworkBaseUrl}/oauth2/token` : undefined),
    oauthUserinfoUrl: process.env.OAUTH_USERINFO_URL ?? (kworkBaseUrl ? `${kworkBaseUrl}/oauth2/userinfo` : undefined),
    oauthRedirectUri: process.env.OAUTH_REDIRECT_URI,
    oauthStateTtlMs: DEFAULT_STATE_TTL,
    ssoTicketTtlMs: DEFAULT_SSO_TICKET_TTL,
    appKey: process.env.APP_KEY,
    // SSO 前端地址从 CORS_ORIGIN 取，运行时 resolveFrontendUrl 用 X-Forwarded-Proto 确保 https
    frontendUrl: process.env.CORS_ORIGIN?.split(',')?.[0]?.trim(),
    // 路由路径（可配置，新应用可覆盖）
    ssoCallbackPath: process.env.SSO_CALLBACK_PATH ?? '/api/auth/sso/callback',
    ssoStartPath: process.env.SSO_START_PATH ?? '/api/auth/sso/start',
    ssoExchangePath: process.env.SSO_EXCHANGE_PATH ?? '/api/auth/sso/exchange',
    loginRoutePath: process.env.LOGIN_ROUTE_PATH ?? '/api/auth/login',
    loginPath: process.env.LOGIN_PATH ?? '/login',
    tokenRedirectPath: process.env.TOKEN_REDIRECT_PATH ?? '/?token={token}',
  }
}

/** 启动校验 — 生产环境 jwtSecret 缺失/默认值时抛异常 */
export function assertConfig(config: AuthKitConfig): void {
  const isProd = process.env.NODE_ENV === 'production'
  if (!config.jwtSecret || config.jwtSecret === DEFAULT_JWT_SECRET) {
    if (isProd) {
      throw new Error('[authkit] JWT_SECRET must be set to a non-default value in production')
    }
    console.warn('[authkit] WARNING: JWT_SECRET is using default value — do not use in production')
  }
}
