// ================================================================
// middleware.ts — 认证中间件工厂
// 导出 requireAnyAuth / requireAdmin / lingeeAuth / webAuth
// requireAnyAuth: x-lingee-code(MCP) 或 Bearer(Web)，互斥，不可同时存在
// requireAdmin: 检查 currentUser.role === 'admin'
// ================================================================

import { randomBytes } from 'node:crypto'
import type { MiddlewareHandler } from 'hono'
import type { ContentfulStatusCode } from 'hono/utils/http-status'
import type {
  AppUser, AuditLogger, AuthEnv, Cache, CredentialUser,
  LoginRouteOptions, PasswordService, TokenService, UserResolver,
} from './types'
import type { AuthKitConfig } from './config'
import { verifyLingeeCode } from './lingee-auth'
import { dbg, maskHash } from './debug'
import { defaultPasswordService } from './password'
import {
  ErrAccountDisabled, ErrAmbiguousCredentials, ErrInsufficientPermissions,
  ErrInvalidAppKey, ErrNotAuthenticated, ErrSessionExpired,
  classifyFailReason,
} from './errors'

export interface AuthMiddlewareOptions<U extends AppUser> {
  userResolver: UserResolver<U>
  tokenService: TokenService
  cache: Cache
  config: AuthKitConfig
  auditLogger?: AuditLogger
  /** 密码服务（可注入，不传用默认 scrypt 实现） */
  passwordService?: PasswordService
}

export interface AuthMiddleware<U extends AppUser> {
  /** 组合认证：x-lingee-code(MCP) 或 Bearer(Web)，互斥 */
  requireAnyAuth: MiddlewareHandler<AuthEnv<U>>
  /** 管理员校验，串联在 requireAnyAuth 之后 */
  requireAdmin: MiddlewareHandler<AuthEnv<U>>
  /** 仅灵基 MCP 通道认证 */
  lingeeAuth: MiddlewareHandler<AuthEnv<U>>
  /** 仅 Web 会话认证 */
  webAuth: MiddlewareHandler<AuthEnv<U>>
  /** 密码登录路由工厂 */
  createLoginRoute: <L extends CredentialUser>(opts: LoginRouteOptions<L>) => MiddlewareHandler
  /** 密码哈希 */
  hashPassword: (password: string) => string
  /** 密码校验 */
  verifyPassword: (password: string, stored: string) => boolean
}

export function createAuthMiddleware<U extends AppUser>(
  opts: AuthMiddlewareOptions<U>,
): AuthMiddleware<U> {
  const { userResolver, tokenService, cache, config, auditLogger } = opts
  const passwordService = opts.passwordService ?? defaultPasswordService

  // --- 审计日志辅助（不记录 token/code 等敏感值）---
  async function audit(
    c: Parameters<MiddlewareHandler<AuthEnv<U>>>[0],
    statusCode: number,
    channel: 'mcp' | 'web',
    user: AppUser | undefined,
    failReason?: string,
  ) {
    if (!auditLogger) return
    await auditLogger.log({
      ts: new Date().toISOString(),
      requestId: c.get('requestId') ?? '-',
      channel,
      localUser: user ? { id: user.id, role: user.role } : undefined,
      method: c.req.method,
      route: c.req.path,
      statusCode,
      failReason: failReason ?? classifyFailReason(statusCode),
    })
  }

  // --- lingeeAuth: x-lingee-code → Console 验证 → 本地用户映射 ---
  const lingeeAuth: MiddlewareHandler<AuthEnv<U>> = async (c, next) => {
    const code = c.req.header('x-lingee-code')
    dbg('lingeeAuth', `── MCP 认证开始 ${c.req.method} ${c.req.path}`)
    if (!code) {
      dbg('lingeeAuth', `FAIL 缺少 x-lingee-code → 401`)
      const res = ErrNotAuthenticated(c)
      await audit(c, 401, 'mcp', undefined, 'auth_failed')
      return res
    }
    dbg('lingeeAuth', `x-lingee-code=${maskHash(code)}…`)

    // 应用级凭证校验（可选，§10.1 第 2 道防线）
    if (config.appKey) {
      const appKey = c.req.header('x-app-key')
      if (appKey !== config.appKey) {
        dbg('lingeeAuth', `FAIL x-app-key 不匹配 → 403`)
        const res = ErrInvalidAppKey(c)
        await audit(c, 403, 'mcp', undefined, 'authz_failed')
        return res
      }
      dbg('lingeeAuth', `x-app-key 校验通过`)
    }

    if (!config.lingeeConsoleUrl) {
      dbg('lingeeAuth', `FAIL LINGEE_CONSOLE_URL 未配置 → 401`)
      const res = ErrNotAuthenticated(c)
      await audit(c, 401, 'mcp', undefined, 'auth_failed')
      return res
    }

    const result = await verifyLingeeCode<U>(code, {
      consoleUrl: config.lingeeConsoleUrl,
      cache,
      config,
      userResolver,
      verifyCacheTtlMs: config.lingeeVerifyCacheTtlMs,
    })

    if (!result.ok) {
      dbg('lingeeAuth', `FAIL verifyLingeeCode → ${result.statusCode} ${result.error}`)
      const res = c.json({ error: result.error }, result.statusCode as ContentfulStatusCode)
      await audit(c, result.statusCode, 'mcp', undefined)
      return res
    }

    dbg('lingeeAuth', `OK 认证成功 user=${result.user.id}(${result.user.role})`)
    c.set('currentUser', result.user)
    c.set('authChannel', 'mcp')
    c.set('lingeeIdentity', result.identity)
    await next()
  }

  // --- webAuth: Bearer token → HMAC 验签 → 本地用户 ---
  const webAuth: MiddlewareHandler<AuthEnv<U>> = async (c, next) => {
    const auth = c.req.header('Authorization')
    dbg('webAuth', `── Web 认证开始 ${c.req.method} ${c.req.path}`)
    if (!auth || !auth.startsWith('Bearer ')) {
      dbg('webAuth', `FAIL 缺少 Bearer token → 401`)
      const res = ErrNotAuthenticated(c)
      await audit(c, 401, 'web', undefined, 'auth_failed')
      return res
    }

    const token = auth.slice(7)
    const payload = tokenService.verify(token)
    if (!payload) {
      dbg('webAuth', `FAIL token 验签失败/过期 → 401`)
      const res = ErrSessionExpired(c)
      await audit(c, 401, 'web', undefined, 'auth_failed')
      return res
    }

    const user = await userResolver.findById(payload.userId)
    if (!user || user.status !== (config.activeStatus ?? 'active')) {
      dbg('webAuth', `FAIL 用户 ${payload.userId} 不存在或 disabled → 401`)
      const res = ErrAccountDisabled(c)
      await audit(c, 401, 'web', user ?? undefined, 'auth_failed')
      return res
    }

    dbg('webAuth', `OK 认证成功 user=${user.id}(${user.role})`)
    c.set('currentUser', user)
    c.set('authChannel', 'web')
    await next()
  }

  // --- requireAnyAuth: 互斥检测 → 认证 → 路由 → 审计 ---
  const requireAnyAuth: MiddlewareHandler<AuthEnv<U>> = async (c, next) => {
    if (!c.get('requestId')) {
      c.set('requestId', randomBytes(8).toString('hex'))
    }

    const hasLingeeCode = !!c.req.header('x-lingee-code')
    const hasBearer = c.req.header('Authorization')?.startsWith('Bearer ') ?? false

    dbg('requireAnyAuth', `── ${c.req.method} ${c.req.path} lingeeCode=${hasLingeeCode} bearer=${hasBearer}`)

    // 两者同时存在 → 拒绝，避免身份来源歧义
    if (hasLingeeCode && hasBearer) {
      dbg('requireAnyAuth', `FAIL x-lingee-code 与 Bearer 同时存在 → 401 Ambiguous`)
      const res = ErrAmbiguousCredentials(c)
      await audit(c, 401, 'mcp', undefined, 'auth_failed')
      return res
    }

    let channel: 'mcp' | 'web' = 'web'
    let authError: { error: string; statusCode: number } | null = null

    if (hasLingeeCode) {
      channel = 'mcp'
      dbg('requireAnyAuth', `分流 → MCP 通道`)
      // 应用级凭证校验（可选，§10.1 第 2 道防线）
      if (config.appKey) {
        const appKey = c.req.header('x-app-key')
        if (appKey !== config.appKey) {
          dbg('requireAnyAuth', `FAIL x-app-key 不匹配 → 403`)
          authError = { error: 'Invalid app key', statusCode: 403 }
        }
      }
      if (!authError && !config.lingeeConsoleUrl) {
        dbg('requireAnyAuth', `FAIL LINGEE_CONSOLE_URL 未配置 → 401`)
        authError = { error: 'Not authenticated', statusCode: 401 }
      }
      if (!authError) {
        const result = await verifyLingeeCode<U>(c.req.header('x-lingee-code')!, {
          consoleUrl: config.lingeeConsoleUrl!,
          cache,
          config,
          userResolver,
          verifyCacheTtlMs: config.lingeeVerifyCacheTtlMs,
        })
        if (!result.ok) {
          dbg('requireAnyAuth', `FAIL verifyLingeeCode → ${result.statusCode} ${result.error}`)
          authError = { error: result.error, statusCode: result.statusCode }
        } else {
          dbg('requireAnyAuth', `OK MCP 认证成功 user=${result.user.id}(${result.user.role})`)
          c.set('currentUser', result.user)
          c.set('authChannel', 'mcp')
          c.set('lingeeIdentity', result.identity)
        }
      }
    } else if (hasBearer) {
      channel = 'web'
      dbg('requireAnyAuth', `分流 → Web 通道`)
      const token = c.req.header('Authorization')!.slice(7)
      const payload = tokenService.verify(token)
      if (!payload) {
        dbg('requireAnyAuth', `FAIL token 验签失败/过期 → 401`)
        authError = { error: 'Session expired, please log in again', statusCode: 401 }
      } else {
        const user = await userResolver.findById(payload.userId)
        if (!user || user.status !== (config.activeStatus ?? 'active')) {
          dbg('requireAnyAuth', `FAIL 用户 ${payload.userId} 不存在或 disabled → 401`)
          authError = { error: 'Account disabled', statusCode: 401 }
        } else {
          dbg('requireAnyAuth', `OK Web 认证成功 user=${user.id}(${user.role})`)
          c.set('currentUser', user)
          c.set('authChannel', 'web')
        }
      }
    } else {
      dbg('requireAnyAuth', `FAIL 无任何认证凭证 → 401`)
      authError = { error: 'Not authenticated', statusCode: 401 }
    }

    // 认证失败 → 返回错误 + 审计
    if (authError) {
      const res = c.json({ error: authError.error }, authError.statusCode as ContentfulStatusCode)
      await audit(c, authError.statusCode, channel, undefined)
      return res
    }

    // 认证成功 → 执行路由
    dbg('requireAnyAuth', `认证通过 → 执行路由 handler`)
    await next()

    // 读操作 + 写操作审计（next 之后记录响应状态码）
    const status = c.res.status
    dbg('requireAnyAuth', `路由完成 → ${status} (${channel})`)
    await audit(c, status, channel, c.get('currentUser'))
  }

  // --- requireAdmin: 检查本地 role === adminRole ---
  const requireAdmin: MiddlewareHandler<AuthEnv<U>> = async (c, next) => {
    const adminRole = config.adminRole ?? 'admin'
    const user = c.get('currentUser')
    if (!user || user.role !== adminRole) {
      dbg('requireAdmin', `FAIL user=${user?.id ?? 'none'} role=${user?.role ?? 'none'} → 403`)
      const res = ErrInsufficientPermissions(c)
      await audit(c, 403, c.get('authChannel') ?? 'web', user, 'authz_failed')
      return res
    }
    dbg('requireAdmin', `OK user=${user.id} 是管理员`)
    await next()
  }

  // --- createLoginRoute: 密码登录路由工厂 ---
  // 应用提供 findByCredential（按手机号/邮箱查用户），返回完整带 passwordHash 的用户
  // 路由内部完成：校验密码 → 检查状态 → 签发 token → 返回响应
  function createLoginRoute<L extends CredentialUser>(
    opts: LoginRouteOptions<L>,
  ): MiddlewareHandler {
    const loginField = opts.loginField ?? 'phone'
    const activeStatus = config.activeStatus ?? 'active'
    return async (c, next) => {
      const body = await c.req.json().catch(() => ({}))
      const identifier = body[loginField] as string | undefined
      const password = body.password as string | undefined
      if (!identifier || !password) {
        return c.json({ error: `${loginField} and password are required` }, 400)
      }
      const user = await opts.findByCredential(identifier)
      if (!user || !passwordService.verify(password, user.passwordHash)) {
        await audit(c, 401, 'web', undefined, 'auth_failed')
        return c.json({ error: `Invalid ${loginField} or password` }, 401)
      }
      if (user.status !== activeStatus) {
        await audit(c, 403, 'web', user, 'authz_failed')
        return c.json({ error: 'Account disabled, please contact administrator' }, 403)
      }
      const token = tokenService.sign(user.id)
      await audit(c, 200, 'web', user)
      if (opts.responseTransform) {
        return c.json(opts.responseTransform(user, token))
      }
      return c.json({ token, user: { id: user.id, role: user.role, status: user.status } })
    }
  }

  return { requireAnyAuth, requireAdmin, lingeeAuth, webAuth, createLoginRoute, hashPassword: passwordService.hash, verifyPassword: passwordService.verify }
}
