// ================================================================
// audit.ts — 审计日志
// 默认 console 输出实现，应用可替换为 SQLite/文件实现
// 脱敏规则：不记录原始 code、access/refresh token、密码、文件内容
// ================================================================

import type { AuditEntry, AuditLogger } from './types'

/** console 审计日志器 — 仅输出非敏感摘要 */
export function createConsoleAuditLogger(): AuditLogger {
  return {
    async log(entry: AuditEntry): Promise<void> {
      const parts = [
        entry.ts,
        `[${entry.channel}]`,
        entry.localUser ? `user=${entry.localUser.id}(${entry.localUser.role})` : 'user=anonymous',
        `${entry.method} ${entry.route}`,
        String(entry.statusCode),
        entry.failReason ?? '',
      ].filter(Boolean)
      console.log(`[audit] ${parts.join(' ')}`)
    },
  }
}
