// ================================================================
// debug.ts — 调试日志工具
// 通过环境变量 DEBUG_AUTHKIT=true 开启
// 脱敏规则：不输出原始 code/token，仅输出 hash 前8位用于链路追踪
// ================================================================

const DEBUG = process.env.DEBUG_AUTHKIT === 'true' || process.env.DEBUG_AUTHKIT === '1'

/** 脱敏：取 hash 前8位作为追踪标识 */
export function maskHash(fullHash: string): string {
  return fullHash.slice(0, 8)
}

/** 脱敏：token 显示 前4…后4 */
export function maskToken(token: string): string {
  if (token.length <= 12) return '***'
  return `${token.slice(0, 4)}…${token.slice(-4)}`
}

/** 条件调试日志，统一前缀 [authkit] */
export function dbg(tag: string, msg: string, ...args: unknown[]): void {
  if (!DEBUG) return
  const ts = new Date().toISOString().slice(11, 23) // 仅时分秒+毫秒
  const parts = args.length > 0 ? ` ${args.map((a) =>
    typeof a === 'string' ? a : JSON.stringify(a)
  ).join(' ')}` : ''
  console.log(`[authkit ${ts}] ${tag} ${msg}${parts}`)
}

/** 调试是否开启 */
export function isDebug(): boolean {
  return DEBUG
}
