// ================================================================
// cache.ts — 内存缓存默认实现
// 支持 TTL 自动过期 + 定期清理
// 多实例/生产环境可替换为 Redis 实现（实现 Cache 接口即可）
// ================================================================

import type { Cache } from './types'
import { dbg } from './debug'

interface CacheEntry {
  value: unknown
  expiresAt: number
}

export function createMemoryCache(): Cache {
  const store = new Map<string, CacheEntry>()

  // 每分钟清理过期条目（unref 不阻止进程退出）
  const timer = setInterval(() => {
    const now = Date.now()
    let cleaned = 0
    for (const [key, entry] of store) {
      if (entry.expiresAt <= now) { store.delete(key); cleaned++ }
    }
    if (cleaned > 0) dbg('cache', `定期清理 ${cleaned} 条过期条目`)
  }, 60_000)
  timer.unref?.()

  return {
    async get<T>(key: string): Promise<T | undefined> {
      const entry = store.get(key)
      if (!entry) {
        dbg('cache', `GET ${key.slice(0, 20)} → MISS`)
        return undefined
      }
      if (entry.expiresAt <= Date.now()) {
        store.delete(key)
        dbg('cache', `GET ${key.slice(0, 20)} → EXPIRED 已删除`)
        return undefined
      }
      dbg('cache', `GET ${key.slice(0, 20)} → HIT`)
      return entry.value as T
    },

    async set<T>(key: string, value: T, ttlMs: number): Promise<void> {
      store.set(key, { value, expiresAt: Date.now() + ttlMs })
      dbg('cache', `SET ${key.slice(0, 20)} TTL=${ttlMs}ms`)
    },

    async delete(key: string): Promise<void> {
      store.delete(key)
      dbg('cache', `DEL ${key.slice(0, 20)}`)
    },
  }
}
